// Serves the Gio's Hub app icon as a real PNG (512x512, full-bleed).
// The mark: a geometric "G" drawn as a hub-and-spoke ring on the hub's dark gradient.
// Source SVG lives in favicon.svg; static copies: icon-192.png, icon-512.png, apple-touch-icon.png.
// Kept so any page or cached manifest still pointing at /api/icon gets the current icon.
const PNG_B64 = "";

module.exports = (req, res) => {
  const buf = Buffer.from(PNG_B64, "base64");
  res.setHeader("Content-Type", "image/png");
  res.setHeader("Cache-Control", "public, max-age=86400");
  res.status(200).end(buf);
};
